package pl.zagranietyper.fixture;
import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import pl.zagranietyper.config.ApiFootballConfig;import pl.zagranietyper.model.ApiFootballFixtureEventsResponse;import java.time.Instant;import static org.junit.jupiter.api.Assertions.*;
class ApiFootballClientEventsTest {private final ApiFootballClient client=new ApiFootballClient(new ApiFootballConfig("test","https://invalid",1,3,0),new ObjectMapper());
 @Test void preservesIdentityChronologyAndEveryRawKind(){String json="""
{"errors":[],"response":[{"time":{"elapsed":45,"extra":2},"team":{"id":10,"name":"Home"},"player":{"id":7,"name":"Scorer"},"assist":{"id":8,"name":"Helper"},"type":"Goal","detail":"Normal Goal","comments":null},{"time":{"elapsed":45,"extra":2},"team":{"id":20,"name":"Away"},"player":{"id":9,"name":"Other"},"assist":{"id":null,"name":null},"type":"Goal","detail":"Penalty","comments":"x"},{"time":{"elapsed":46,"extra":null},"team":{"id":10,"name":"Home"},"player":{"id":7,"name":"Scorer"},"assist":{"id":null,"name":null},"type":"Goal","detail":"Own Goal","comments":null},{"time":{"elapsed":60},"team":{"id":20},"player":{"id":9,"name":"Other"},"assist":{},"type":"Card","detail":"Yellow Card"},{"time":{"elapsed":61},"team":{"id":20},"player":{"id":9},"assist":{},"type":"Card","detail":"Red Card"},{"time":{"elapsed":62},"team":{"id":20},"player":{"id":9},"assist":{},"type":"Card","detail":"Second Yellow card"},{"time":{"elapsed":63},"team":{"id":20},"player":{"id":9},"assist":{},"type":"Goal","detail":"Missed Penalty"},{"time":{"elapsed":64},"team":{"id":20},"player":{"id":9},"assist":{},"type":"subst","detail":"Substitution 1"},{"time":{"elapsed":65},"team":{"id":20},"player":{"id":9},"assist":{},"type":"Mystery","detail":"Unknown detail"}]}
""";var r=client.parseFixtureEvents(json,99,200,Instant.EPOCH);assertEquals(ApiFootballFixtureEventsResponse.Status.SUCCESS,r.status());assertEquals(9,r.events().size());assertEquals(0,r.events().get(0).sourceIndex());assertEquals(1,r.events().get(1).sourceIndex());assertEquals(2,r.events().getFirst().extraMinute());assertEquals(8L,r.events().getFirst().assistPlayerId());assertEquals("Own Goal",r.events().get(2).detail());assertEquals("Missed Penalty",r.events().get(6).detail());assertEquals("Mystery",r.events().get(8).type());}
 @Test void distinguishesEmptyApiErrorAndParseError(){assertEquals(ApiFootballFixtureEventsResponse.Status.EMPTY,client.parseFixtureEvents("{\"errors\":[],\"response\":[]}",1,200,Instant.EPOCH).status());assertEquals(ApiFootballFixtureEventsResponse.Status.API_ERROR,client.parseFixtureEvents("{\"errors\":{\"fixture\":\"bad\"},\"response\":[]}",1,200,Instant.EPOCH).status());assertEquals(ApiFootballFixtureEventsResponse.Status.PARSE_ERROR,client.parseFixtureEvents("bad",1,200,Instant.EPOCH).status());}
}
